import type { createAdmin, createStorefront, initialize } from "arky-sdk";
import type {
  Account,
  AccountAccess,
  AccountToken,
  AccountTokenStores,
  CreateAccountTokenParams,
  CreateStoreParams,
  CreateStorePlan,
  CreateStoreType,
  EpochMilliseconds,
  FeatureType,
  FindResendEventsParams,
  FindStripeBillingEventsParams,
  IncomingWebhookType,
  Network,
  NetworkPayments,
  NetworkPlan,
  NetworkPlanPrice,
  OutgoingEmailType,
  PlanLimit,
  RequestPendingAccountSessionParams,
  ResolveResendEventParams,
  ResolveStripeBillingEventParams,
  Store,
  StoreCardSetup,
  StorefrontIdentity,
  StorefrontOptions,
  StoreSubscription,
  StoreSubscriptionPayment,
  StoreSubscriptionPlan,
  StoreType,
} from "arky-sdk";

type Assert<T extends true> = T;
type Equal<A, B> = (<T>() => T extends A ? 1 : 2) extends <T>() => T extends B ? 1 : 2 ? true : false;
type Missing<T, K extends PropertyKey> = K extends keyof T ? false : true;
type RequiredField<T, K extends keyof T> = {} extends Pick<T, K> ? false : true;
type Admin = ReturnType<typeof createAdmin>;
type NetworkSignIn = Extract<RequestPendingAccountSessionParams, { network_id: string }>;

export type NetworkStoreContracts = [
  Assert<Equal<Parameters<typeof createStorefront>, [StorefrontIdentity, StorefrontOptions]>>,
  Assert<Equal<Parameters<typeof initialize>, [StorefrontIdentity, StorefrontOptions]>>,
  Assert<Equal<StorefrontIdentity, { storeId: string; salesChannelId: string }>>,
  Assert<Equal<Store["type"], StoreType>>,
  Assert<Equal<StoreType, { type: "live"; account_id: string; network_id: string } | { type: "test"; store_id: string }>>,
  Assert<Equal<Store["status"]["type"], "active" | "wiping" | "deleting">>,
  Assert<Missing<Store, "owner_account_id" | "mode" | "network_id">>,
  Assert<Equal<CreateStoreParams["type"], CreateStoreType>>,
  Assert<Equal<CreateStorePlan, { type: "free"; plan_id: string } | { type: "card"; plan_id: string; setup_intent_id: string } | { type: "grant"; plan_id: string }>>,
  Assert<Equal<Account["access"], AccountAccess>>,
  Assert<Equal<AccountAccess, { type: "regular" } | { type: "platform_admin" }>>,
  Assert<Missing<Account, "type" | "test_stores">>,
  Assert<Equal<AccountTokenStores, { type: "all" } | { type: "only"; store_ids: string[] }>>,
  Assert<Missing<AccountToken, "permissions">>,
  Assert<Missing<CreateAccountTokenParams, "permissions">>,
  Assert<RequiredField<NetworkSignIn, "network_id">>,
  Assert<Equal<Network["payments"], NetworkPayments>>,
  Assert<Equal<NetworkPayments, { type: "none" } | { type: "stripe"; account_id: string; publishable_key: string }>>,
  Assert<Missing<Network, "stripe">>,
  Assert<Missing<Extract<NetworkPayments, { type: "stripe" }>, "secret_key" | "encrypted_secret_key" | "webhook_secret" | "encrypted_webhook_secret">>,
  Assert<Equal<keyof Network["email"], "from_name" | "from_address" | "resend_webhook_id" | "sign_in_subject" | "sign_in_body">>,
  Assert<Equal<PlanLimit, { type: "unlimited" } | { type: "max"; count: number }>>,
  Assert<Equal<NetworkPlanPrice["type"], "free" | "lifetime" | "monthly" | "yearly">>,
  Assert<Equal<Extract<NetworkPlanPrice, { type: "free" }>, { type: "free" }>>,
  Assert<Missing<Extract<NetworkPlanPrice, { type: "lifetime" }>, "trial_days" | "months" | "years">>,
  Assert<RequiredField<Extract<NetworkPlanPrice, { type: "monthly" }>, "months">>,
  Assert<RequiredField<Extract<NetworkPlanPrice, { type: "yearly" }>, "years">>,
  Assert<Equal<NetworkPlan["features"], Record<FeatureType, PlanLimit>>>,
  Assert<Equal<Extract<FeatureType, "test_stores">, "test_stores">>,
  Assert<Missing<NetworkPlan, "status" | "visibility" | "provider_price_id" | "interval">>,
  Assert<Equal<StoreSubscription["plan"], StoreSubscriptionPlan>>,
  Assert<Equal<StoreSubscriptionPlan["type"], "granted" | "trialing" | "active" | "past_due" | "cancellation_scheduled" | "unpaid" | "cancelled">>,
  Assert<Equal<Extract<StoreSubscriptionPlan, { type: "trialing" }>["trial_ends_at"], EpochMilliseconds>>,
  Assert<Equal<Extract<StoreSubscriptionPlan, { type: "active" }>["paid_until"], EpochMilliseconds>>,
  Assert<Missing<Extract<StoreSubscriptionPlan, { type: "unpaid" }>, "paid_until">>,
  Assert<Equal<Extract<StoreSubscriptionPlan, { type: "cancelled" }>, { type: "cancelled"; plan_id: string }>>,
  Assert<Equal<Awaited<ReturnType<Admin["store"]["subscription"]["createCardSetup"]>>, StoreCardSetup>>,
  Assert<Equal<Awaited<ReturnType<Admin["store"]["subscription"]["pendingPayment"]>>, StoreSubscriptionPayment>>,
  Assert<Missing<Admin["store"]["subscription"], "select" | "createPortalSession" | "getPlans">>,
  Assert<Missing<Admin["store"], "apiKey">>,
  Assert<Missing<Admin["platform"], "administrator">>,
  Assert<RequiredField<FindStripeBillingEventsParams, "network_id">>,
  Assert<RequiredField<ResolveStripeBillingEventParams, "network_id">>,
  Assert<RequiredField<FindResendEventsParams, "network_id">>,
  Assert<RequiredField<ResolveResendEventParams, "network_id">>,
  Assert<Equal<Extract<IncomingWebhookType, { type: "stripe_billing" }>["network_id"], string>>,
  Assert<Equal<Extract<IncomingWebhookType, { type: "network_resend" }>["network_id"], string>>,
  Assert<Equal<Extract<IncomingWebhookType, { type: "resend" }>, never>>,
  Assert<Equal<Extract<OutgoingEmailType, { type: "network_sign_in" }>, { type: "network_sign_in"; network_id: string }>>,
  Assert<Equal<Extract<OutgoingEmailType, { type: "arky_sign_in" }>, never>>,
  Assert<Missing<StoreSubscription, "entries" | "billing_entries">>,
];
